// src/services/MockBackend.js
class MockBackend {
  constructor() {
    this.rooms = new Map();
    this.listeners = new Map();
    this.loadFromStorage();
    this.startStorageListener();
  }

  // Load all rooms from localStorage
  loadFromStorage() {
    const saved = localStorage.getItem('watchparty_rooms');
    if (saved) {
      const roomsData = JSON.parse(saved);
      roomsData.forEach(roomData => {
        const room = {
          roomId: roomData.roomId,
          participants: new Map(),
          state: roomData.state
        };
        // Rebuild Map from array
        roomData.participants.forEach(([key, value]) => {
          room.participants.set(key, value);
        });
        this.rooms.set(roomData.roomId, room);
      });
    }
  }

  // Save all rooms to localStorage
  saveToStorage() {
    const roomsData = [];
    this.rooms.forEach(room => {
      roomsData.push({
        roomId: room.roomId,
        participants: Array.from(room.participants.entries()),
        state: room.state
      });
    });
    localStorage.setItem('watchparty_rooms', JSON.stringify(roomsData));
    // Trigger storage event for other tabs
    window.dispatchEvent(new StorageEvent('storage', {
      key: 'watchparty_rooms',
      newValue: JSON.stringify(roomsData)
    }));
  }

  // Listen for changes from other tabs
  startStorageListener() {
    window.addEventListener('storage', (event) => {
      if (event.key === 'watchparty_rooms' && event.newValue) {
        // Reload data
        this.loadFromStorage();
        // Notify all listeners to refresh
        this.rooms.forEach((room, roomId) => {
          this.notifyListeners(roomId, 'refresh', null);
          // Also send current participants
          const participants = Array.from(room.participants.values());
          participants.forEach(p => {
            this.notifyListeners(roomId, 'user_joined', p);
          });
        });
      }
      
      if (event.key && event.key.startsWith('wp_event_')) {
        try {
          const eventData = JSON.parse(event.newValue);
          this.processEvent(eventData);
          // Clean up
          setTimeout(() => localStorage.removeItem(event.key), 100);
        } catch(e) {}
      }
    });
  }

  // Send event to all tabs
  sendEvent(eventData) {
    const eventKey = `wp_event_${Date.now()}_${Math.random()}`;
    localStorage.setItem(eventKey, JSON.stringify(eventData));
  }

  processEvent(eventData) {
    const { roomId, type, payload, senderId } = eventData;
    const room = this.rooms.get(roomId);
    if (!room) return;
    
    const sender = room.participants.get(senderId);
    if (!sender) return;
    
    switch(type) {
      case 'join':
        if (!room.participants.has(senderId)) {
          const newParticipant = {
            userId: senderId,
            username: payload.username,
            role: room.participants.size === 0 ? 'HOST' : 'PARTICIPANT',
            joinedAt: new Date()
          };
          room.participants.set(senderId, newParticipant);
          this.saveToStorage();
          
          // Notify everyone about new participant
          this.notifyListeners(roomId, 'user_joined', newParticipant);
          
          // Send current state to new user
          this.notifyListeners(roomId, 'state_update', room.state);
        }
        break;
        
      case 'play':
        if (sender.role === 'HOST' || sender.role === 'MODERATOR') {
          room.state.isPlaying = true;
          this.saveToStorage();
          this.notifyListeners(roomId, 'play', { currentTime: room.state.currentTime });
        }
        break;
        
      case 'pause':
        if (sender.role === 'HOST' || sender.role === 'MODERATOR') {
          room.state.isPlaying = false;
          this.saveToStorage();
          this.notifyListeners(roomId, 'pause', { currentTime: room.state.currentTime });
        }
        break;
        
      case 'seek':
        if (sender.role === 'HOST' || sender.role === 'MODERATOR') {
          room.state.currentTime = payload.time;
          this.saveToStorage();
          this.notifyListeners(roomId, 'seek', { time: payload.time });
        }
        break;
        
      case 'change_video':
        if (sender.role === 'HOST' || sender.role === 'MODERATOR') {
          room.state.videoId = payload.videoId;
          room.state.currentTime = 0;
          room.state.isPlaying = false;
          this.saveToStorage();
          this.notifyListeners(roomId, 'change_video', { videoId: payload.videoId });
        }
        break;
        
      case 'assign_role':
        if (sender.role === 'HOST') {
          const target = room.participants.get(payload.targetId);
          if (target) {
            target.role = payload.role;
            this.saveToStorage();
            this.notifyListeners(roomId, 'role_assigned', {
              userId: payload.targetId,
              role: payload.role
            });
          }
        }
        break;
        
      case 'remove_participant':
        if (sender.role === 'HOST') {
          room.participants.delete(payload.targetId);
          this.saveToStorage();
          this.notifyListeners(roomId, 'participant_removed', {
            userId: payload.targetId
          });
        }
        break;
        
      case 'chat':
        this.notifyListeners(roomId, 'chat', {
          username: payload.username,
          message: payload.message
        });
        break;
        
      case 'leave':
        const leaver = room.participants.get(senderId);
        if (leaver) {
          room.participants.delete(senderId);
          this.saveToStorage();
          this.notifyListeners(roomId, 'user_left', {
            userId: senderId,
            username: leaver.username
          });
        }
        break;
    }
  }

  notifyListeners(roomId, type, payload) {
    if (this.listeners.has(roomId)) {
      this.listeners.get(roomId).forEach(callback => {
        try {
          callback(type, payload);
        } catch(e) {}
      });
    }
  }

  createRoom(roomId, hostId, hostUsername) {
    if (this.rooms.has(roomId)) {
      return this.rooms.get(roomId);
    }
    
    const room = {
      roomId,
      participants: new Map(),
      state: {
        videoId: 'dQw4w9WgXcQ',
        isPlaying: false,
        currentTime: 0
      }
    };
    
    room.participants.set(hostId, {
      userId: hostId,
      username: hostUsername,
      role: 'HOST',
      joinedAt: new Date()
    });
    
    this.rooms.set(roomId, room);
    this.saveToStorage();
    return room;
  }

  joinRoom(roomId, userId, username) {
    const room = this.rooms.get(roomId);
    if (!room) return null;
    
    // Send join event
    this.sendEvent({
      roomId,
      type: 'join',
      payload: { username },
      senderId: userId
    });
    
    // Process locally
    this.processEvent({
      roomId,
      type: 'join',
      payload: { username },
      senderId: userId
    });
    
    return {
      roomId,
      userId,
      role: room.participants.get(userId)?.role || 'PARTICIPANT',
      state: room.state
    };
  }

  subscribe(roomId, callback) {
    if (!this.listeners.has(roomId)) {
      this.listeners.set(roomId, new Set());
    }
    this.listeners.get(roomId).add(callback);
    
    return () => {
      if (this.listeners.has(roomId)) {
        this.listeners.get(roomId).delete(callback);
      }
    };
  }

  sendPlay(roomId, userId) {
    this.sendEvent({ roomId, type: 'play', payload: {}, senderId: userId });
    this.processEvent({ roomId, type: 'play', payload: {}, senderId: userId });
  }

  sendPause(roomId, userId) {
    this.sendEvent({ roomId, type: 'pause', payload: {}, senderId: userId });
    this.processEvent({ roomId, type: 'pause', payload: {}, senderId: userId });
  }

  sendSeek(roomId, userId, time) {
    this.sendEvent({ roomId, type: 'seek', payload: { time }, senderId: userId });
    this.processEvent({ roomId, type: 'seek', payload: { time }, senderId: userId });
  }

  sendChangeVideo(roomId, userId, videoId) {
    this.sendEvent({ roomId, type: 'change_video', payload: { videoId }, senderId: userId });
    this.processEvent({ roomId, type: 'change_video', payload: { videoId }, senderId: userId });
  }

  sendAssignRole(roomId, userId, targetId, role) {
    this.sendEvent({ roomId, type: 'assign_role', payload: { targetId, role }, senderId: userId });
    this.processEvent({ roomId, type: 'assign_role', payload: { targetId, role }, senderId: userId });
  }

  sendRemoveParticipant(roomId, userId, targetId) {
    this.sendEvent({ roomId, type: 'remove_participant', payload: { targetId }, senderId: userId });
    this.processEvent({ roomId, type: 'remove_participant', payload: { targetId }, senderId: userId });
  }

  sendChat(roomId, userId, username, message) {
    this.sendEvent({ roomId, type: 'chat', payload: { username, message }, senderId: userId });
    this.processEvent({ roomId, type: 'chat', payload: { username, message }, senderId: userId });
  }

  sendLeave(roomId, userId) {
    this.sendEvent({ roomId, type: 'leave', payload: {}, senderId: userId });
    this.processEvent({ roomId, type: 'leave', payload: {}, senderId: userId });
  }

  getRoom(roomId) {
    return this.rooms.get(roomId);
  }

  getParticipants(roomId) {
    const room = this.rooms.get(roomId);
    return room ? Array.from(room.participants.values()) : [];
  }

  getRoomState(roomId) {
    const room = this.rooms.get(roomId);
    return room ? room.state : null;
  }
}

const mockBackend = new MockBackend();
export default mockBackend;
